parameters.jsCode:
// Nominatim returns one item per listing. Keep only the fields a prospect
// list needs, and dedupe on name + address so repeat listings collapse.
// Honest note: Nominatim listings rarely carry a website or phone — most
// rows will have those blank. That is normal for free public data.
const seen = new Set();
const rows = [];
const pushRow = (raw) => {
  if (!raw || typeof raw !== 'object') return;
  const display = raw.display_name || '';
  const name = (raw.name || display.split(',')[0] || '').trim();
  if (!name || !display) return;
  const key = (name + '|' + display).toLowerCase();
  if (seen.has(key)) return;
  seen.add(key);
  const addr = raw.address || {};
  const tags = raw.extratags || {};
  rows.push({ json: {
    business_name: name,
    category: raw.type || raw.class || '',
    address: display,
    suburb: addr.suburb || addr.neighbourhood || '',
    city: addr.city || addr.town || addr.village || '',
    website: tags.website || tags['contact:website'] || raw.website || '',
    phone: tags.phone || tags['contact:phone'] || raw.phone || '',
    email: '',
    source: 'OpenStreetMap'
  }});
};
for (const item of $input.all()) {
  if (Array.isArray(item.json)) { item.json.forEach(pushRow); } else { pushRow(item.json); }
}
return rows;

// Scan ONLY the business's own public website for contact details it has
// chosen to publish: a mailto: link first, then a plain-text email, then
// a phone number. Nothing is guessed and nothing comes from third parties.
const listings = $('Normalise & Dedupe Listings').all().filter(i => i.json.website);
const pages = $input.all();
return pages.map((item, idx) => {
  const listing = (listings[idx] && listings[idx].json) || {};
  let html = '';
  if (typeof item.json === 'string') html = item.json;
  else if (item.json) html = item.json.data || item.json.body || item.json.text || '';
  const mailto = html.match(/mailto:([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/i);
  const plain = html.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
  const phone = html.match(/(\+?\d[\d\s().-]{7,}\d)/);
  const email = listing.email || (mailto ? mailto[1] : (plain ? plain[0] : ''));
  return { json: {
    ...listing,
    email: String(email).toLowerCase(),
    phone: listing.phone || (phone ? phone[1].trim() : ''),
    contact_page_found: !!(email || phone)
  }};
});

